import{promises as fs}from'node:fs';for(const p of['scripts/build.mjs','assets'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}`)});let b=await fs.readFile('scripts/build.mjs','utf8');if(!b.includes('V25.9 direct nav-links')){b+='\n'+await fs.readFile('v25-9-build-patch.txt','utf8');await fs.writeFile('scripts/build.mjs',b)}await fs.copyFile('menu-v259.css','assets/menu-v259.css');await fs.copyFile('menu-v259.js','assets/menu-v259.js');console.log('V25.9 kuruldu: yanlış kapsayıcı seçicisi kaldırıldı; menü doğrudan .nav-links üzerinden yeniden kurulacak.');
